#### depth first

```cpp
#include <vector>
#include <unordered_map>
#include <tuple>

std::unordered_map<int, std::vector<int>> buildGraph(int numNodes, std::vector<std::tuple<int, int>> edges) {
  std::unordered_map<int, std::vector<int>> graph;

  for (int node = 0; node < numNodes; node += 1) {
    graph[node] = std::vector<int>();
  }

  for (std::tuple<int, int> edge : edges) {
    auto [a, b] = edge;
    graph[a].push_back(b);
  }

  return graph;
}


int exploreDistance(std::unordered_map<int, std::vector<int>> graph, std::unordered_map<int, int> &distance, int node) {
  if (distance.count(node) > 0) {
    return distance[node];
  }

  int maxDistance = 0;
  for (int neighbor : graph[node]) {
    int neighborDistance = exploreDistance(graph, distance, neighbor);
    if (neighborDistance > maxDistance) {
      maxDistance = neighborDistance;
    }
  }

  distance[node] = 1 + maxDistance;
  return distance[node];
}

int semestersRequired(int numCourses, std::vector<std::tuple<int, int>> prereqs) {
  std::unordered_map<int, std::vector<int>> graph = buildGraph(numCourses, prereqs);

  std::unordered_map<int, int> distance;
  for (auto [node, neighbors] : graph) {
    if (neighbors.size() == 0) {
      distance[node] = 1;
    }
  }

  int max = 0;
  for (auto [node, neighbors] : graph) {
    int dist = exploreDistance(graph, distance, node);
    if (dist > max) {
      max = dist;
    }
  }

  return max;
}
```

- p = # prereqs
- c = # courses
- Time: O(p)
- Space: O(c)
